    const take = Math.min(limit ?? 50, 200)

    let rows = await ctx.db
      .query('curated_routes')
      .withIndex('by_geometry_status', (q) => q.eq('geometryStatus', 'review'))
      .take(take * 3)

    if (routeIdPrefix) {
      rows = rows.filter((r) => r.routeId.startsWith(routeIdPrefix))
